 x.source('spec','Yarn, hook and sample specification|纱线钩针与样品规格',txt('spec','A makes six small dolphins with fine yarn F and 4 mm hooks. B makes four large dolphins with thick yarn T and 6 mm hooks. Both are the same pattern; larger print means larger lettering, not a larger hook. Each learner needs one hook for the class. Two verified 4 mm spare hooks belong to the host and may replace uncertain tools without asking anyone.|A六人用细线F及4毫米钩针做小海豚；B四人用粗线T及6毫米做大海豚。花样相同，大字是字大，不是钩针大。每人上课需一支。主人有两支已核4毫米备针，可替不明工具，不用再问。'),field('class-state','Actual class outcomes|实际课堂状态',{'A':'not_started','B':'not_started'}))
 for name in ['a','b']:
  x.source('kit-'+name,'Actual kit '+name.upper()+' image|'+name.upper()+'实际工具包图片',image('kit-'+name+'-image','assets/t5-04/kit-'+name+'.png','Current tools and labels in this kit. Match visible size labels and any unlabelled pieces to the specification.|本包当前工具与标签，请按可见尺寸和无标签件对照规格。'),field('kit-'+name+'-state','Actual selected kit '+name.upper()+'|'+name.upper()+'实际所选工具包',{'hook_size':None,'yarn':None,'packed':False,'ready':False,'delivered':False,'destination':'store'}))
  service_at(x,'kit-'+name,'kit-'+name,'Allocate selects the actual hook size and yarn for this class. Pack inspects that selection and reports whether the kit is ready. A’s unlabelled pieces need an actual label remedy or verified spares; B’s fully labelled set is independent.|分配为本班选择实际针号与纱线；打包检查所选内容并报告是否就绪。A无标签件需实际补标或已核备件，B完整标签套装独立。',{'allocate':option('Select matching hooks and yarn|选配钩针与纱线',schema={'hook_size':[4,6],'yarn':['F','T']},parameter_record={'resource':'kit-'+name+'-state','field':'allocation','field_map':{'hook_size':'hook_size','yarn':'yarn'}}),'pack':option('Pack and inspect selected kit|打包检查所选工具包',set={'kit-'+name+'-state':{'packed':True,'ready':name=='b'}},**({'add':[txt('unlabelled-feedback','Two hook pockets in A lack size labels. The kit is packed but not ready to teach. You may use the verified spares or match the photographed tools to the same-scale gauge and label them. Do not send unknown tools as confirmed 4 mm.|A有两格钩针没尺寸标签，已打包但不能直接教。可用已核备针，或按同尺度量规比对照片后补标，别把未知工具当已确认4毫米发出去。','receipt')]} if name=='a' else {})),'deliver':option('Deliver packed kit to its booked classroom|将工具包实际送进已订教室',requires={'fields':{'kit-'+name+'-state':{'ready':True}}},set={'kit-'+name+'-state':{'delivered':True,'destination':'room-'+name}})})
 x.c['lookups']['card/kit-a'].append(image('gauge-image','assets/t5-04/gauge.png','Same-scale tool gauge. Compare the unlabelled hooks in kit A to these silhouettes.|同尺度工具量规，请将A包无标签钩针对照轮廓。'))
 x.find('kit-a')['options'] += [{'key':'use-spares','description':T('Use two verified 4 mm host spares|用两支已核4毫米自有备针')},{'key':'label','description':T('Apply measured size label to the two original hooks|给两支原针贴实测尺寸标签'),'param_schema':{'measured_mm':[4,6]}}]
 x.c['operations']['kit-a/use-spares']={'requires':{'fields':{'kit-a-state':{'packed':True}}},'set':{'kit-a-state':{'ready':True,'remedy':'verified_spares','hook_size':4}},'facts':{'used_host_spares':2,'uncertain_originals':'retained_in_store'}}
 x.c['operations']['kit-a/label']={'param_schema':{'measured_mm':[4,6]},'parameter_record':{'resource':'kit-a-state','field':'label','field_map':{'measured_mm':'hook_size'}},'set':{'kit-a-state':{'ready':True,'remedy':'labelled_originals'}}}
